"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import { chordIntervals, Complexity, generateChordProgression, generateMelody, getScale, MelodyMood, Mode, notePitchClass, Root } from "../packages/music-theory";
import { beatDurationSeconds, calculateTapTempo, DRUM_INSTRUMENTS, DrumHit, DrumInstrument, DrumStyle, generateDrumLoop, isAccentedStep, melodyLoopDurationMs, progressionLoopDurationMs, subdivisionDurationSeconds } from "../packages/sequencing";

type Idea = { id: string; type: "audio" | "chords" | "melody" | "drums" | "text"; name: string; detail: string; recordingId?: string; data?: string[] };
type SongSection = { id: string; name: string; bars: number; color: string; ideas: Idea[] };
type Project = { id: string; name: string; bpm: number; meter: string; key: string; updated: number; sections: SongSection[] };
type Screen = "home" | "projects" | "project" | "chords" | "melody" | "drums" | "metronome" | "settings";
type ChordDraft = { id: string; name: string; beats: number };

const ROOTS: Root[] = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"];
const MODES: Mode[] = ["major", "minor", "dorian", "phrygian", "lydian", "mixolydian", "harmonic minor", "minor pentatonic"];
const COLORS = ["mint", "violet", "amber", "blue", "coral"];
const uid = () => Math.random().toString(36).slice(2, 10);
const clampBpm = (bpm: number) => Math.max(30, Math.min(260, Number.isFinite(bpm) ? Math.round(bpm) : 120));
const titleMode = (mode: Mode) => mode.replace(/\b\w/g, letter => letter.toUpperCase());
const normalizeAccidentals = (value: string) => value.replace(/C#/g, "Db").replace(/D#/g, "Eb").replace(/F#/g, "Gb").replace(/G#/g, "Ab").replace(/A#/g, "Bb");
const midiNoteName = (pitch: number) => `${ROOTS[((pitch % 12) + 12) % 12]}${Math.floor(pitch / 12) - 1}`;
const projectHarmony = (project?: Project): { root: Root; mode: Mode } => {
  const [savedRoot = "C", ...savedMode] = normalizeAccidentals(project?.key ?? "C major").split(" ");
  const root = ROOTS.includes(savedRoot as Root) ? savedRoot as Root : "C";
  const mode = savedMode.join(" ").toLowerCase() as Mode;
  return { root, mode: MODES.includes(mode) ? mode : "major" };
};
const formatProjectKey = (root: Root, mode: Mode) => `${root} ${titleMode(mode)}`;
const makeChordDrafts = (root: Root, mode: Mode, count: number, complexity: Complexity, seed: number, defaultBeats = 4, variation = 0): ChordDraft[] =>
  generateChordProgression({ root, mode, bars: count, complexity, seed }).map((chord, index) => {
    const wiggle = Math.round((variation / 100) * Math.max(1, defaultBeats - 1));
    const offset = wiggle ? ((Math.abs(seed * 31 + index * 17) % (wiggle * 2 + 1)) - wiggle) : 0;
    return { id: uid(), name: chord.name, beats: Math.max(1, Math.min(8, defaultBeats + offset)) };
  });
const decodeChordDrafts = (idea: Idea): ChordDraft[] => (idea.data?.length ? idea.data : idea.detail.split(" · ")).map(value => { const [name, savedBeats] = value.split("|"); return { id: uid(), name, beats: Number(savedBeats) || 4 }; });
const decodeMelodyIdea = (idea: Idea) => (idea.data?.length ? idea.data : idea.detail.split(" · ")).map((value, index) => { const [note, start, duration, pitch] = value.split("|"); return { note, start: Number(start) || index * .5, duration: Number(duration) || .45, pitch: Number(pitch) || 60 + (notePitchClass(note) ?? 0), velocity: .72 }; });
const isDrumInstrument = (value: string): value is DrumInstrument => (DRUM_INSTRUMENTS as readonly string[]).includes(value);
const decodeDrumIdea = (idea: Idea): DrumHit[] => (idea.data ?? []).map(value => { const [instrument, step, velocity] = value.split("|"); return isDrumInstrument(instrument) ? { instrument, step: Number(step) || 0, velocity: Number(velocity) || .7 } : null; }).filter((hit): hit is DrumHit => hit !== null);
const chordRole = (symbol: string, root: Root, mode: Mode) => {
  const degree = getScale(root, mode).findIndex(note => notePitchClass(note) === notePitchClass(symbol));
  if (degree < 0) return "chromatic";
  const suffix = symbol.replace(/^[A-G](?:b|#)?/, ""); const diminished = /dim|°/.test(suffix); const minor = diminished || /^m(?!aj)/.test(suffix);
  const numeral = ["I", "II", "III", "IV", "V", "VI", "VII"][degree]; const role = ["tonic / root", "supertonic", "mediant", "subdominant", "dominant", "submediant", "leading tone"][degree];
  return `${minor ? numeral.toLowerCase() : numeral}${diminished ? "°" : ""} · ${role}`;
};

